const TK=[['dart','Dart'],['oop','OOP'],['flutter','Flutter']];
let tcount=0;
const TASKJ={};const tkc=(lv,tr,q,hint,code,src)=>{tcount++;const sols=Array.isArray(code)?code:[code];TASKJ['#'+tcount]={q:String(q),hint:hint?String(hint):'',sols:sols.map(String)};return `<article class="tk rv" data-lv="${lv}" data-tr="${tr}"><div class="tk-h"><span class="badge">${src}</span><span class="tk-n">#${tcount}</span></div><p class="tk-q">${esc(q)}</p>${hint?`<p class="hint">${T('تلميح:','Hint:')} <bdi>${esc(hint)}</bdi></p>`:''}<div class="aibox"><textarea class="fld tka" rows="4" maxlength="2000" ${ph('اكتب إجابتك هنا. الحل بيتفتح بعد محاولتين','Write your answer here. The solution unlocks after 2 attempts')}></textarea><div class="ai-row"><button class="btn tksub" type="button" disabled>${T('قدّم محاولتي','Submit my attempt')}</button><button class="btn ghost tkai" type="button" disabled>${T('تقييم AI (قريبًا)','AI grade (soon)')}</button><span class="tkmsg ai-soon"></span></div></div><p class="tklock">${T('الحل بيتفتح بعد محاولتين.','The solution unlocks after 2 attempts.')}</p><details class="ans" hidden><summary>${T('اعرض الإجابة','Show answer')}</summary><div class="sols" data-i="0">${sols.map((c,i)=>`<div class="sol"${i?' hidden':''}>${sols.length>1?`<p class="sol-n">${T('الحل','Solution')} ${i+1} / ${sols.length}</p>`:''}${block('Answer',c,'dart')}</div>`).join('')}${sols.length>1?`<button type="button" class="btn alt-b" data-n="${sols.length}">${T('حل تاني / فكرة مختلفة','Another solution')} ↻</button>`:''}</div></details></article>`};
let tlist='';
L.forEach(l=>{const an=ANSWERS[l.n];if(l.task&&an)tlist+=tkc('basic','dart',l.task.text,l.task.hint,an.code,T('الدرس','Lesson')+' '+l.n)});
LV.forEach(v=>TK.forEach(t=>(XT[t[0]][v[0]]||[]).forEach(x=>{tlist+=tkc(v[0],t[0],x.q,x.hint,x.a,T('تمرين','Practice'))})));
JSON.parse(fs.readFileSync('lesson_tasks.json','utf8')).forEach(x=>{tlist+=tkc(x.lv,'dart',x.q,x.hint,x.a,T('تمرين الدرس','Exercise, Lesson')+' '+x.n)});
write('tasks',head('التاسكات | Mobile App A to Z','اختبر نفسك بتاسكات من المبتدئ للمتقدم في Dart و OOP و Flutter.')+`<main class="wrap lesson">${crumb(A('',T('الرئيسية','Home')),T('التاسكات','Tasks'))}<div class="sec-h"><div><span class="kick">${T('اختبر نفسك','Test yourself')}</span><h2>${T('التاسكات','Tasks')}</h2></div></div><p class="cm-note">${T('اختار مستواك والمسار، حاول تحل لوحدك، وبعدها اعرض الإجابة.','Pick your level and track, try on your own, then show the answer.')}</p><div class="tkbar" id="tkbar"><div class="pills" data-g="lv">${LV.map((v,i)=>`<button type="button" class="pill${i===0?' on':''}" data-v="${v[0]}">${T(v[1],v[2])}</button>`).join('')}</div><div class="pills" data-g="tr"><button type="button" class="pill on" data-v="all">${T('الكل','All')}</button>${TK.map(t=>`<button type="button" class="pill" data-v="${t[0]}">${t[1]}</button>`).join('')}</div></div><div class="tkgrid" id="tkgrid">${tlist}</div><nav class="tkpg" id="tkpg" aria-label="Pages"></nav><p class="soon" id="tkempty" hidden>${T('مفيش تاسكات هنا لسه.','No tasks here yet.')}</p></main>`+foot+`<script>(function(){var lv=localStorage.getItem('tk_lv')||'basic',tr='all',pg=1;function ap(){var m=[].filter.call(document.querySelectorAll('#tkgrid .tk'),function(e){return e.dataset.lv===lv&&(tr==='all'||e.dataset.tr===tr)});var PS=6,np=Math.max(1,Math.ceil(m.length/PS));if(pg>np)pg=np;document.querySelectorAll('#tkgrid .tk').forEach(function(e){e.hidden=true});m.forEach(function(e,i){e.hidden=!(i>=(pg-1)*PS&&i<pg*PS)});document.getElementById('tkempty').hidden=m.length>0;var pe=document.getElementById('tkpg'),h='';if(np>1){h+='<button type="button" class="pgb" data-p="'+Math.max(1,pg-1)+'" aria-label="Previous"'+(pg===1?' disabled':'')+'>›</button>';for(var i=1;i<=np;i++)h+='<button type="button" class="pgb'+(i===pg?' on':'')+'" data-p="'+i+'"'+(i===pg?' aria-current="page"':'')+'>'+i+'</button>';h+='<button type="button" class="pgb" data-p="'+Math.min(np,pg+1)+'" aria-label="Next"'+(pg===np?' disabled':'')+'>‹</button>'}pe.innerHTML=h;document.querySelectorAll('.pills[data-g=lv] .pill').forEach(function(b){b.classList.toggle('on',b.dataset.v===lv)});document.querySelectorAll('.pills[data-g=tr] .pill').forEach(function(b){b.classList.toggle('on',b.dataset.v===tr)})}document.getElementById('tkgrid').addEventListener('click',function(e){var a=e.target.closest('.alt-b');if(!a)return;var w=a.parentNode,ss=w.querySelectorAll('.sol'),i=(+w.dataset.i+1)%ss.length;w.dataset.i=i;ss.forEach(function(x,k){x.hidden=k!==i})});document.getElementById('tkbar').addEventListener('click',function(e){var b=e.target.closest('.pill');if(!b)return;if(b.parentNode.dataset.g==='lv'){lv=b.dataset.v;try{localStorage.setItem('tk_lv',lv)}catch(x){}}else tr=b.dataset.v;pg=1;ap()});document.getElementById('tkpg').addEventListener('click',function(e){var b=e.target.closest('.pgb');if(!b||b.disabled)return;pg=+b.dataset.p;ap();var g=document.getElementById('tkbar');window.scrollTo({top:g.getBoundingClientRect().top+scrollY-80,behavior:'smooth'})});ap()})()</script>`);
write('lessons',head('الدروس | Mobile App A to Z','كل دروس القناة مقسمة حسب المسارات.')+
`<main class="wrap lesson">${crumb(A('',T('الرئيسية','Home')),T('الدروس','Lessons'))}<div class="sec-h"><div><span class="kick">${T('الدروس','Lessons')}</span><h2>${T('كل الدروس حسب المسار','All lessons by track')}</h2></div><button class="count sb2" type="button" id="sbtn2"><svg class="mi" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><circle cx="11" cy="11" r="7"/><path d="M20 20l-3.5-3.5"/></svg> ${T('بحث','Search')}</button></div>`+
TRACKS.map(t=>{const ls=tl(t);return `<section class="tsec" id="${t.id}"><div class="tsec-h rv"><span class="ti">${t.icon}</span><div><h3>${t.name}</h3><small>${T(t.sub,TEN[t.id][0])}</small></div><a class="go" href="${base}tracks/${t.id}/">${T('صفحة المسار ←','Track page →')}</a></div>`+(ls.length?`<div class="grid cap">${ls.map(lcard).join('')}${t.id==='dart'?soonCard(M+1)+soonCard(M+2):''}</div>`+`<div class="more"><button type="button" class="btn ghost" onclick="var g=this.parentNode.previousElementSibling;g.classList.add('open');this.parentNode.hidden=true">${T('عرض المزيد','Show more')} ↓</button><a class="btn ghost" href="${base}tracks/${t.id}/">${T('كل دروس المسار ←','Full track →')}</a></div>`:`<div class="soon rv">${T('الدروس دي قريبًا. تابعنا على يوتيوب وتيك توك.','These lessons are coming soon. Follow us on YouTube and TikTok.')}</div>`)+`</section>`}).join('')+`</main>`+foot);
// tracks
for(const t of TRACKS){const ls=tl(t);
 write('tracks/'+t.id,head(`${t.name} | Mobile App A to Z`,t.desc)+`<main class="wrap lesson">${crumb(A('',T('الرئيسية','Home')),A('lessons/',T('الدروس','Lessons')),t.name)}<div class="thead rv"><span class="ti big">${t.icon}</span><div><span class="kick">${T('مسار','Track')}</span><h1>${t.name}</h1><p class="lead">${T(t.desc,TEN[t.id][1])}</p></div></div>`+
 (ls.length?`<div class="trackbar rv" data-t="${t.id}" data-ls="${ls.map(x=>x.n).join(',')}"><div class="tp"><div class="tbar"><i></i></div><span class="tpt" data-total="${ls.length}">0/${ls.length}</span></div></div><div class="grid">${ls.map(lcard).join('')}${t.id==='dart'?soonCard(M+1)+soonCard(M+2):''}</div>`:`<div class="soon rv">${T('الدروس دي قريبًا. تابعنا على يوتيوب وتيك توك عشان تعرف أول ما تنزل.','These lessons are coming soon. Follow us on YouTube and TikTok to know when they drop.')}</div>`)+
 `<div class="pn"><a href="${base}#tracks">${T('→ كل المسارات','← All tracks')}</a><a href="${base}lessons/">${T('كل الدروس ←','All lessons →')}</a></div></main>`+foot);}
// lesson pages
const sideList=(cur,t)=>`<aside class="side"><div class="panel"><div class="side-t">${T('دروس مسار','Track lessons:')} ${t.name}</div><div class="sl">`+tl(t).map(x=>`<a class="${x.n===cur?'cur':''}" href="${base}lesson-${x.n}/"><b>${String(x.n).padStart(2,'0')}</b><span>${esc(x.title)}</span><em class="sdn">✓</em></a>`).join('')+`</div></div><div class="panel"><div class="side-t">${T('روابط سريعة','Quick links')}</div><a class="ql" href="${YT}" target="_blank" rel="noopener">▶ YouTube</a><a class="ql" href="${TT}" target="_blank" rel="noopener">♪ TikTok</a><a class="ql" href="${base}#contact">✉ ${T('تواصل معنا','Contact us')}</a></div></aside>`;
for(const l of L){
  const t=TRACKS.find(x=>x.id===trackOf(l)); const tls=tl(t); const idx=tls.indexOf(l);
  const prev=ANSWERS[l.n-1]; const next=L.find(x=>x.n===l.n+1), pv=L.find(x=>x.n===l.n-1);
  const tabs=[['code','الأكواد','Code',l.snippets.length>0],['notes','الملاحظات','Notes',true],['task','التاسك','Task',!!l.task],['ans','إجابة تاسك الدرس '+(l.n-1),'Answer to Lesson '+(l.n-1)+' task',!!prev],['faq','أسئلة شائعة','FAQ',!!FAQ[l.n]]].filter(x=>x[3]);
  const first=tabs[0][0];
  const faqH=(FAQ[l.n]||[]).map(f=>`<details class="faqi"><summary>${T(f[0],f[1])}</summary><p>${T(esc(f[2]),esc(f[3]))}</p></details>`).join('')+`<p class="cm-note"><a href="${base}errors/">${T('أخطاء شائعة في Dart و Flutter وحلولها ←','Common Dart and Flutter errors and fixes →')}</a></p>`;
  const panes={faq:faqH,
   code:l.snippets.map(s=>block(s.title,s.code,s.lang)).join(''),
   notes:`<ul class="notes">${l.notes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`,
   task:l.task?`<div class="box task"><h3>${T('تاسك الدرس','Lesson task')} ${l.n}</h3><p>${esc(l.task.text)}</p>${l.task.hint?`<p class="hint">${T('تلميح:','Hint:')} <bdi>${esc(l.task.hint)}</bdi></p>`:''}<p class="hint">${T(`الإجابة في فيديو الدرس ${l.n+1} وفي صفحة الدرس ${l.n+1}.`,`The answer is in the Lesson ${l.n+1} video and page.`)}</p></div>`:'',
   ans:prev?`<div class="box answer"><h3>${T('إجابة تاسك الدرس','Answer to the task of Lesson')} ${l.n-1}</h3><p>${esc(prev.task)}</p>${block('Answer: Lesson '+(l.n-1),prev.code)}</div>`:''};
  const id=ytid(l.youtube);
  const h=head(`الدرس ${l.n}: ${l.title} | Mobile App A to Z`,`ملاحظات وأكواد وتاسك ${l.title}`)+
  `<main class="wrap lesson" data-lesson="${l.n}" data-title="${esc(l.title)}">${crumb(A('',T('الرئيسية','Home')),A('lessons/',T('الدروس','Lessons')),A('tracks/'+t.id+'/',t.name),T('الدرس','Lesson')+' '+l.n)}
  <div class="l-head"><div><span class="badge">${T('الدرس','Lesson')} ${l.n} ${T('من','of')} ${M}</span><h1>${esc(l.title)}</h1></div></div><div class="prog"><i style="width:${Math.round(100*(idx+1)/tls.length)}%"></i></div><div class="mypr" data-ls="${tls.map(x=>x.n).join(',')}"><span>${T('تقدمك في مسار','Your progress in')} ${t.name}:</span> <b class="mp">0/${tls.length}</b></div>
  <div class="dl"><div class="main-col">
  <section class="panel"><div class="player"><iframe id="ytp" data-n="${l.n}" src="https://www.youtube-nocookie.com/embed/${id}?rel=0&enablejsapi=1" title="${esc(l.title)}" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div><div class="vbar"><a class="ytlink" href="${l.youtube}" target="_blank" rel="noopener">${IC.yt} ${T('افتح على يوتيوب','Open on YouTube')}</a><button class="bkbtn" type="button" data-n="${l.n}" aria-pressed="false"><span class="b0">☆ ${T('احفظ الدرس','Save lesson')}</span><span class="b1">★ ${T('محفوظ','Saved')}</span></button><button class="donebtn" type="button" data-n="${l.n}"><span class="d0">☐ ${T('علّم الدرس كمكتمل','Mark lesson as done')}</span><span class="d1">✓ ${T('الدرس مكتمل','Lesson completed')}</span></button></div><div class="wprog" id="wprog" hidden><div class="wbar"><i id="wbi"></i></div><small id="wtx"></small></div></section>
  <section class="panel"><div class="tabs" role="tablist">${tabs.map(x=>`<button class="tab${x[0]===first?' on':''}" data-tab="${x[0]}">${T(x[1],x[2])}</button>`).join('')}</div>`+
  tabs.map(x=>`<div class="pane" id="pane-${x[0]}"${x[0]===first?'':' hidden'}>${panes[x[0]]}</div>`).join('')+`</section>
  <div class="pn">${next?`<a href="${base}lesson-${next.n}/">${T('الدرس','Lesson')} ${next.n} ${T('←','→')}</a>`:'<span></span>'}${pv?`<a href="${base}lesson-${pv.n}/">${T('→','←')} ${T('الدرس','Lesson')} ${pv.n}</a>`:''}</div>
  ${QUIZ[l.n]?`<section class="panel" id="quiz" data-n="${l.n}" data-q="${esc(JSON.stringify(QUIZ[l.n].map(q=>({q:q.q,o:q.o}))))}"><h3 class="ct">${T('اختبار الدرس','Lesson quiz')} ${l.n}</h3><p class="cm-note">${T('5 أسئلة. كل إجابة صح بنقطة (الحد الأقصى 5). عندك 3 محاولات والأعلى هو اللي بيتحسب. التصحيح من السيرفر.','5 questions. Each correct answer is 1 point (max 5). You get 3 attempts and your best counts. Graded on the server.')}</p><div id="quizbox"></div></section>`:''}
  <section class="panel" id="mynote" data-n="${l.n}"><h3 class="ct">${T('ملاحظاتي على الدرس','My notes on this lesson')}</h3><p class="cm-note">${T('خاصة بيك. بتتحفظ تلقائي، وبتتزامن مع حسابك لما تسجل دخول.','Private to you. Saved automatically, and synced to your account when you sign in.')}</p><textarea class="fld" id="mynotetx" rows="5" maxlength="2000" dir="auto" ${ph('اكتب ملاحظاتك هنا...','Write your notes here...')}></textarea><small id="mynotest" class="mu"></small></section>
  <section class="panel" id="qa" data-lesson="${l.n}"><h3 class="ct">${T('أسئلة وأجوبة','Questions and answers')}</h3><p class="cm-note">${T('اسأل عن الدرس أو جاوب على سؤال حد. اكتب اسمك الحقيقي، مش محتاج حساب. اللي سأل السؤال يقدر يختار أفضل إجابة. أي حاجة مش مناسبة دوس "إبلاغ".','Ask about the lesson or answer someone. Use your real name, no account needed. The person who asked can pick the best answer. Press "Report" on anything inappropriate.')}</p><form class="cform" id="qaform" novalidate><input class="fld" name="nm" maxlength="40" required autocomplete="name" ${ph('اسمك الحقيقي (مطلوب)','Your real name (required)')}><textarea class="fld" name="tx" rows="3" maxlength="1000" required ${ph('اكتب سؤالك...','Write your question...')}></textarea><input class="hp" name="website" tabindex="-1" autocomplete="off" aria-hidden="true"><div class="cm-row"><button class="btn" type="submit">${T('أرسل السؤال','Post question')}</button><span class="cm-msg" id="qamsg" role="status"></span></div></form><div id="qalist" class="qalist"></div></section>
  </div>${sideList(l.n,t)}</div></main>`+foot;
  write('lesson-'+l.n,h);
}

