if(PUB){fs.mkdirSync('/downloads/wr/functions',{recursive:true});{const LJ={};L.forEach(l=>{if(l.dur)LJ[l.n]=l.dur});fs.writeFileSync('/downloads/wr/functions/_lessons.json',JSON.stringify(LJ))}fs.writeFileSync('/downloads/wr/functions/_tasks.json',JSON.stringify(TASKJ));fs.writeFileSync('/downloads/wr/functions/_dq.json',JSON.stringify(Object.values(QUIZ).flat().map(q=>({q:q.q,o:q.o,a:q.a}))));fs.writeFileSync('/downloads/wr/functions/_quiz.json',JSON.stringify(Object.fromEntries(Object.entries(QUIZ).map(([k,v])=>[k,v.map(q=>q.a)]))))}
if(PUB){{const sn=x=>x.snippets&&x.snippets.length?x.snippets.map(c=>'['+c.title+']\n'+c.code).join('\n'):'';const help='Site help: The site has Lessons (each with the video, notes and code with copy buttons), Tasks (levels and tracks; two attempts then the solution unlocks; AI grading needs sign-in), a Leaderboard (task points and 10 points per lesson watched 90% for real), Start here page, settings (profile, privacy, notifications).';fs.writeFileSync('/downloads/wr/functions/_kb.json',JSON.stringify({text:help+'\n\n'+L.map(x=>'LESSON '+x.n+': '+x.title+'\nNotes:\n- '+(x.notes||[]).join('\n- ')+'\nCode:\n'+sn(x)).join('\n\n')}))}
}
try{const sp=out+'/sitemap.xml';if(fs.existsSync(sp))fs.writeFileSync(sp,fs.readFileSync(sp,'utf8').split('\n').filter(l=>!l.includes('/nf/')).join('\n'));if(fs.existsSync(out+'/nf/index.html')){fs.copyFileSync(out+'/nf/index.html',out+'/404.html');fs.rmSync(out+'/nf',{recursive:true})}}catch(e){console.log('post',e.message)}
